codesense.subscribeContext({ text: "DEMO" }, (rows) => {
  render(rows); // called on initial + on each nudge
});

// Equivalent — but DO NOT emit directly:
window.parent.postMessage(
  { type: "codesense:invoke", id, command: "queryContext", args: {} },
  "*",
);
// Just:
codesense.invoke("queryContext", {});

// Posted automatically by the shim.
window.addEventListener("message", (e) => {
  if (e.data?.type === "codesense:ready") init();
});

// Handled by the shim; opt in to pre-serialize work:
window.addEventListener("message", (e) => {
  if (e.data?.type !== "codesense:snapshot-request") return;
  // prepare the DOM before serialization
});
